-- ============================================================
-- Migration 169 -- Crash courses, Class 1 only: introduction, Foundational English Assessment, diagnostic test
--
-- Live's IELTS Academic Crash Course still showed Week 1 as "Orientation, Diagnostic & Listening Start" with one item
-- ("Orientation & Diagnostic Assessment"): the state migration 134 copied from the 2-Month Masterclass. Every later
-- crash-course change (151, 153, 157, 158, 160, 161) found the course by its LOCAL id (23; 10, 12, 18 for the others),
-- so on live, where the ids differ, they changed nothing and said nothing.
--
-- Founder, 2026-10-24: Class 1 of each crash course holds the introduction, the Foundational English Assessment and the
-- diagnostic test, in the order: course introduction, Foundational English Assessment, exam introduction, exam quiz,
-- diagnostic test (founder, 2026-10-24). Each crash course has its own Course Introduction and exam introduction pages. This sets CLASS 1 ONLY (Week 1, first class) of the four crash courses, found by courses.folder_name,
-- to the five items local has (generated from local): its title, first page and items. The class keeps its id (progress
-- stays). Nothing else changes: no other class, no week title, no 2- or 3-month course.
-- Run AFTER 168 (the Foundational English Assessment items point at its test, FEA50_A).
-- One transaction. Re-runnable. MySQL 5.7-safe. The SELECT at the end lists each crash course's Class 1 items.
-- ============================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- ---------------- IELTS_Gen_1Mo ----------------
DELETE p FROM lesson_parts p JOIN lessons l ON l.id = p.lesson_id JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id AND c.folder_name = 'IELTS_Gen_1Mo' WHERE m.module_order = 1 AND l.lesson_order = 1;
UPDATE lessons l JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id AND c.folder_name = 'IELTS_Gen_1Mo' SET l.title = 'Class 1: Course Introduction + Foundational English Assessment + IELTS General Introduction + IELTS Format Knowledge Quiz + IELTS General Training Diagnostic Test', l.file_path = 'courses/IELTS_Gen_1Mo/lessons/class01_p1_course-introduction.php' WHERE m.module_order = 1 AND l.lesson_order = 1;
INSERT INTO lesson_parts (lesson_id, part_order, title, kind, status, file_path, test_code, pass_percent) SELECT l.id, 1, 'Course Introduction', 'lesson', 'ready', 'courses/IELTS_Gen_1Mo/lessons/class01_p1_course-introduction.php', NULL, NULL FROM lessons l JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id AND c.folder_name = 'IELTS_Gen_1Mo' WHERE m.module_order = 1 AND l.lesson_order = 1;
INSERT INTO lesson_parts (lesson_id, part_order, title, kind, status, file_path, test_code, pass_percent) SELECT l.id, 2, 'Foundational English Assessment', 'placement_test', 'ready', 'resources/placement/foundational_english_assessment.php', 'FEA50_A', NULL FROM lessons l JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id AND c.folder_name = 'IELTS_Gen_1Mo' WHERE m.module_order = 1 AND l.lesson_order = 1;
INSERT INTO lesson_parts (lesson_id, part_order, title, kind, status, file_path, test_code, pass_percent) SELECT l.id, 3, 'IELTS General Introduction', 'lesson', 'ready', 'courses/IELTS_Gen_1Mo/lessons/class01_p3_ielts-general-introduction.php', NULL, NULL FROM lessons l JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id AND c.folder_name = 'IELTS_Gen_1Mo' WHERE m.module_order = 1 AND l.lesson_order = 1;
INSERT INTO lesson_parts (lesson_id, part_order, title, kind, status, file_path, test_code, pass_percent) SELECT l.id, 4, 'IELTS General Introduction Quiz', 'quiz', 'ready', 'resources/quizzes/class_quiz.php?test_code=IELTS_GT_C1_QUIZ', 'IELTS_GT_C1_QUIZ', 70 FROM lessons l JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id AND c.folder_name = 'IELTS_Gen_1Mo' WHERE m.module_order = 1 AND l.lesson_order = 1;
INSERT INTO lesson_parts (lesson_id, part_order, title, kind, status, file_path, test_code, pass_percent) SELECT l.id, 5, 'IELTS General Training Diagnostic Test', 'diagnostic_test', 'ready', 'resources/mock_tests/ielts_gt_diagnostic.php', 'IELTS_GT_DIAGNOSTIC', NULL FROM lessons l JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id AND c.folder_name = 'IELTS_Gen_1Mo' WHERE m.module_order = 1 AND l.lesson_order = 1;

