-- Expected: each crash course's Class 1 lists its 5 items: course introduction, Foundational English Assessment,
-- exam introduction, exam quiz, diagnostic test.
SELECT c.folder_name, p.part_order, p.title, p.kind, p.status
  FROM courses c JOIN modules m ON m.course_id = c.id AND m.module_order = 1 JOIN lessons l ON l.module_id = m.id AND l.lesson_order = 1
  JOIN lesson_parts p ON p.lesson_id = l.id WHERE c.folder_name IN ('IELTS_Gen_1Mo', 'CELPIP_Gen_1Mo', 'PTE_Gen_1Mo', 'IELTS_Aca_1Mo') ORDER BY c.folder_name, p.part_order;
